using System;using System.Linq;using ForteMove.Models.Assignments;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin.Operations{public partial class ExceptionDetails:AdminPage{private long Id{get{long x;return long.TryParse(Request.QueryString["id"],out x)?x:0;}}private long TripId{get{return (long)(ViewState["TripId"]??0L); }set{ViewState["TripId"]=value;}}protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){var d=ServiceFactory.CreateOperationsAdminService().GetCannotProceedDetails(Id);if(d==null){Response.Redirect(ResolveUrl("~/Admin/Operations/Exceptions.aspx"),true);return;}var maintenanceBus=ServiceFactory.CreateMaintenanceService().GetBuses().FirstOrDefault(b=>b.FleetNumber==d.FleetNumber);lnkMaintenance.Visible=maintenanceBus!=null;if(maintenanceBus!=null)lnkMaintenance.NavigateUrl="~/Admin/Maintenance/CreateWorkOrder.aspx?busId="+maintenanceBus.BusId+"&exceptionId="+Id;TripId=d.TripId;litTrip.Text=Server.HtmlEncode(d.TripCode);litRoute.Text=Server.HtmlEncode(d.RouteName);litDriver.Text=Server.HtmlEncode(d.EmployeeNumber+" · "+d.DriverName);litBus.Text=Server.HtmlEncode(d.FleetNumber);litPhase.Text=Server.HtmlEncode(d.Phase.ToString());litStatus.Text=Server.HtmlEncode(d.TripStatus.ToString().Replace("InProgress","In progress"));litReason.Text=Server.HtmlEncode(d.Reason);litNote.Text=Server.HtmlEncode(d.Note??string.Empty);hidReportRv.Value=Convert.ToBase64String(d.RowVersion);hidTripRv.Value=Convert.ToBase64String(d.TripRowVersion);AssignmentDetails a=ServiceFactory.CreateAssignmentService().GetDetails(d.TripId);hidAssignmentRv.Value=a!=null&&a.CurrentAssignment!=null?Convert.ToBase64String(a.CurrentAssignment.RowVersion):string.Empty;pnlResolution.Visible=d.IsOpen;pnlResolved.Visible=!d.IsOpen;if(!d.IsOpen)litResolved.Text=Server.HtmlEncode((d.ResolutionType.HasValue?d.ResolutionType.Value.ToString():"Resolved")+": "+d.ResolutionNote);}protected void btnProceed_Click(object s,EventArgs e){var r=ServiceFactory.CreateOperationsAdminService().AllowProceed(new ResolveCannotProceedRequest{TripCannotProceedReportId=Id,ResolutionNote=txtResolution.Text,ReportRowVersion=Parse(hidReportRv.Value),TripRowVersion=Parse(hidTripRv.Value)},CurrentPrincipalContext.UserAccountId);Show(r,"Trip may proceed.");}protected void btnCancel_Click(object s,EventArgs e){var r=ServiceFactory.CreateOperationsAdminService().CancelTrip(new CancelTripRequest{TripId=TripId,Reason=txtResolution.Text,TripRowVersion=Parse(hidTripRv.Value),AssignmentRowVersion=Parse(hidAssignmentRv.Value)},CurrentPrincipalContext.UserAccountId);Show(r,"Trip cancelled.");}private void Show(ForteMove.Models.Common.ServiceResult<bool> r,string success){pnlMessage.CssClass=r.Succeeded?"alert alert-success":"alert alert-danger";litMessage.Text=Server.HtmlEncode(r.Succeeded?success:string.Join(" ",r.Errors.Select(x=>x.Message)));pnlMessage.Visible=true;Bind();}private static byte[] Parse(string x){try{return Convert.FromBase64String(x);}catch{return null;}}}}
